1	/**
2	 * multi-sensor.js - 统一传感器管理器
3	 *
4	 * 管理加速度计、陀螺仪、心率、气压计、指南针的订阅。
5	 * 设备不支持或模拟器环境下自动降级为模拟数据。
6	 */
7	
8	import sensor from "@system.sensor"
9	
10	var activeSubscriptions = {}
11	
12	// ─── 模拟数据生成 ────────────────────────────────────────
13	
14	function mockAccel() {
15	  return { x: 0.03 * Math.sin(Date.now() / 900), y: 0.02 * Math.cos(Date.now() / 700), z: 1 + 0.04 * Math.sin(Date.now() / 1100) }
16	}
17	
18	function mockGyro() {
19	  return { x: 0.02 * Math.sin(Date.now() / 800), y: 0.015 * Math.cos(Date.now() / 650), z: 0.01 * Math.sin(Date.now() / 500) }
20	}
21	
22	var mockHRBase = 72
23	var mockHRDrift = 0
24	
25	function mockHeartRate() {
26	  mockHRDrift += (Math.random() - 0.5) * 0.4
27	  if (mockHRDrift > 6) { mockHRDrift = 6 }
28	  if (mockHRDrift < -6) { mockHRDrift = -6 }
29	  var hr = mockHRBase + mockHRDrift + 0.8 * Math.sin(Date.now() / 15000)
30	  return { heartRate: Math.round(hr) }
31	}
32	
33	function mockBarometer() {
34	  return { pressure: 1013.25 + 0.15 * Math.sin(Date.now() / 30000) }
35	}
36	
37	function mockCompass() {
38	  return { direction: 180 + 2 * Math.sin(Date.now() / 20000), accuracy: 3 }
39	}
40	
41	// ─── 模拟数据回放 ────────────────────────────────────────
42	
43	var mockTimer = null
44	var mockCallbacks = {}
45	
46	function startMockReplay() {
47	  if (mockTimer) { return }
48	  mockTimer = setInterval(function () {
49	    var types = Object.keys(mockCallbacks)
50	    for (var i = 0; i < types.length; i++) {
51	      var type = types[i]
52	      var callbacks = mockCallbacks[type]
53	      if (!callbacks || !callbacks.length) { continue }
54	      var sample = null
55	      if (type === "accelerometer") { sample = mockAccel() }
56	      else if (type === "gyroscope") { sample = mockGyro() }
57	      else if (type === "heartrate") { sample = mockHeartRate() }
58	      else if (type === "barometer") { sample = mockBarometer() }
59	      else if (type === "compass") { sample = mockCompass() }
60	      if (sample) {
61	        for (var j = 0; j < callbacks.length; j++) {
62	          try { callbacks[j](sample) } catch (e) { console.log("mock callback error", e) }
63	        }
64	      }
65	    }
66	  }, 100)
67	}
68	
69	function stopMockReplay() {
70	  if (mockTimer) {
71	    clearInterval(mockTimer)
72	    mockTimer = null
73	  }
74	}
75	
76	function registerMockCallback(type, callback) {
77	  if (!mockCallbacks[type]) { mockCallbacks[type] = [] }
78	  mockCallbacks[type].push(callback)
79	  startMockReplay()
80	}
81	
82	function removeMockCallback(type, callback) {
83	  if (!mockCallbacks[type]) { return }
84	  var list = []
85	  for (var i = 0; i < mockCallbacks[type].length; i++) {
86	    if (mockCallbacks[type][i] !== callback) { list.push(mockCallbacks[type][i]) }
87	  }
88	  mockCallbacks[type] = list
89	  var total = 0
90	  var types = Object.keys(mockCallbacks)
91	  for (var j = 0; j < types.length; j++) { total += mockCallbacks[types[j]].length }
92	  if (total === 0) { stopMockReplay() }
93	}
94	
95	// ─── 订阅管理 ──────────────────────────────────────────
96	
97	export function subscribeAccelerometer(callback, options) {
98	  var useMock = options && options.forceMock
99	  if (!useMock) {
100	    try {
101	      sensor.subscribeAccelerometer({
102	        interval: (options && options.interval) || "game",
103	        callback: function (data) { activeSubscriptions.accelerometer = true; callback(data) },
104	        fail: function () { useMock = true; registerMockCallback("accelerometer", callback); activeSubscriptions.accelerometer = "mock" }
105	      })
106	      activeSubscriptions.accelerometer = true
107	      return
108	    } catch (e) { useMock = true }
109	  }
110	  registerMockCallback("accelerometer", callback)
111	  activeSubscriptions.accelerometer = "mock"
112	}
113	
114	export function subscribeGyroscope(callback, options) {
115	  var useMock = options && options.forceMock
116	  if (!useMock) {
117	    try {
118	      sensor.subscribeGyroscope({
119	        interval: (options && options.interval) || "game",
120	        callback: function (data) { activeSubscriptions.gyroscope = true; callback(data) },
121	        fail: function () { registerMockCallback("gyroscope", callback); activeSubscriptions.gyroscope = "mock" }
122	      })
123	      activeSubscriptions.gyroscope = true
124	      return
125	    } catch (e) { useMock = true }
126	  }
127	  registerMockCallback("gyroscope", callback)
128	  activeSubscriptions.gyroscope = "mock"
