144	  activeSubscriptions.heartrate = "mock"
145	}
146	
147	export function subscribeBarometer(callback, options) {
148	  var useMock = options && options.forceMock
149	  if (!useMock) {
150	    try {
151	      sensor.subscribeBarometer({
152	        callback: function (data) { activeSubscriptions.barometer = true; callback(data) },
153	        fail: function () { registerMockCallback("barometer", callback); activeSubscriptions.barometer = "mock" }
154	      })
155	      activeSubscriptions.barometer = true
156	      return
157	    } catch (e) { useMock = true }
158	  }
159	  registerMockCallback("barometer", callback)
160	  activeSubscriptions.barometer = "mock"
161	}
162	
163	export function subscribeCompass(callback, options) {
164	  var useMock = options && options.forceMock
165	  if (!useMock) {
166	    try {
167	      sensor.subscribeCompass({
168	        callback: function (data) { activeSubscriptions.compass = true; callback(data) },
169	        fail: function () { registerMockCallback("compass", callback); activeSubscriptions.compass = "mock" }
170	      })
171	      activeSubscriptions.compass = true
172	      return
173	    } catch (e) { useMock = true }
174	  }
175	  registerMockCallback("compass", callback)
176	  activeSubscriptions.compass = "mock"
177	}
178	
179	// ─── 取消订阅 ──────────────────────────────────────────
180	
181	export function unsubscribeAll() {
182	  try { sensor.unsubscribeAccelerometer() } catch (e) { /* skip */ }
183	  try { sensor.unsubscribeGyroscope() } catch (e) { /* skip */ }
184	  try { sensor.unsubscribeHeartRate() } catch (e) { /* skip */ }
185	  try { sensor.unsubscribeBarometer() } catch (e) { /* skip */ }
186	  try { sensor.unsubscribeCompass() } catch (e) { /* skip */ }
187	  activeSubscriptions = {}
188	  stopMockReplay()
189	  mockCallbacks = {}
190	}
191	
192	export function getSubscriptionStatus() {
193	  return activeSubscriptions
194	}
195	
196	// ─── 外部模拟数据注入（供场景回放使用） ────────────────────
197	
198	export function injectMockSample(type, sample) {
199	  var callbacks = mockCallbacks[type]
200	  if (!callbacks) { return }
201	  for (var i = 0; i < callbacks.length; i++) {
202	    try { callbacks[i](sample) } catch (e) { /* skip */ }
203	  }
204	}
205	
206	export function setMockBaselineHR(hr) {
207	  mockHRBase = hr
208	  mockHRDrift = 0
209	}
210	
211	export function resetMockHR() {
212	  mockHRBase = 72
213	  mockHRDrift = 0
214	}
215	
216	// ─── 步数估算 ──────────────────────────────────────────
217	
218	var stepCount = 0
219	var lastStepTime = 0
220	var STEP_THRESHOLD = 1.25
221	var STEP_DEBOUNCE_MS = 280
222	
223	export function resetStepCount() {
224	  stepCount = 0
225	  lastStepTime = 0
226	}
227	
228	export function getStepCount() {
229	  return stepCount
230	}
231	
232	export function processStepDetection(sample) {
233	  var g = Math.sqrt(sample.x * sample.x + sample.y * sample.y + sample.z * sample.z)
234	  var now = Date.now()
235	  if (g > STEP_THRESHOLD && now - lastStepTime > STEP_DEBOUNCE_MS) {
236	    stepCount += 1
237	    lastStepTime = now
238	  }
239	  return stepCount
240	}
241	
242	// ─── 气压趋势 ──────────────────────────────────────────
243	
244	var pressureHistory = []
245	
246	export function recordPressure(pressure) {
247	  pressureHistory.push({ value: pressure, time: Date.now() })
248	  if (pressureHistory.length > 120) { pressureHistory.shift() }
249	}
250	
251	export function getPressureTrend() {
252	  if (pressureHistory.length < 10) { return { delta: 0, trend: "stable" } }
253	  var recent = pressureHistory.slice(-30)
254	  var old = pressureHistory.slice(0, Math.min(30, pressureHistory.length))
255	  var recentAvg = 0
256	  var oldAvg = 0
257	  for (var i = 0; i < recent.length; i++) { recentAvg += recent[i].value }
258	  for (var j = 0; j < old.length; j++) { oldAvg += old[j].value }
259	  recentAvg /= recent.length
260	  oldAvg /= old.length
261	  var delta = recentAvg - oldAvg
262	  var trend = "stable"
263	  if (delta < -0.3) { trend = "falling" }
264	  else if (delta > 0.3) { trend = "rising" }
265	  return { delta: Math.round(delta * 100) / 100, trend: trend }
266	}
267	
268	// ─── 心率历史 ──────────────────────────────────────────
269	
270	var hrHistory = []
271	
272	export function recordHeartRate(hr) {
273	  hrHistory.push({ value: hr, time: Date.now() })
274	  if (hrHistory.length > 3600) { hrHistory.shift() }
275	}
276	
277	export function getHRHistory() {
278	  return hrHistory
279	}
280	
281	export function getHRAverage(seconds) {
282	  if (!hrHistory.length) { return 0 }
283	  var cutoff = Date.now() - seconds * 1000
284	  var sum = 0
285	  var count = 0
286	  for (var i = hrHistory.length - 1; i >= 0; i--) {
287	    if (hrHistory[i].time < cutoff) { break }
288	    sum += hrHistory[i].value
289	    count += 1
290	  }
291	  return count > 0 ? Math.round(sum / count) : 0
292	}
293	
294	export function getHRZone(hr) {
295	  if (hr < 60) { return { zone: "rest", label: "静息", color: "#5ba8ff" } }
296	  if (hr < 100) { return { zone: "normal", label: "正常", color: "#64e9b8" } }
297	  if (hr < 140) { return { zone: "elevated", label: "偏高", color: "#ffd27e" } }
298	  return { zone: "high", label: "过高", color: "#ff6b6b" }
299	}
300	
301	export function estimateCalories(hr, durationMin) {
302	  return Math.round(hr * 0.05 * durationMin)
303	}
304	
305	export function isActive(hr) {
306	  return hr > 100
307	}
308	
309	export function getMaxHR(age) {
310	  return 220 - age
311	}
