1	/**
2	 * fall-detector.js - 两阶段跌倒 / 异常静止检测状态机
3	 *
4	 * 解决"4 秒窗口单次命中即告警"导致的高误报：
5	 *
6	 *   跌倒：阶段一捕获"冲击峰值"只标记候选，不告警；
7	 *         阶段二要求冲击后"持续静止"达到阈值时长才确认。
8	 *         期间只要佩戴者恢复明显运动（起身、甩手、继续走）
9	 *         就立刻取消候选，从而抑制"猛坐下/跳跃/磕手腕/摘表"
10	 *         等冲击型误报。
11	 *
12	 *   异常静止：不再用 4 秒低活动判定，而是要求"曾出现过活动
13	 *          → 之后持续低活动"达到更长时间（30s）才上报，
14	 *          避免把"一直静止佩戴"当成异常。
15	 *
16	 * 与 fall-model.js 的 12 维决策树配合：本状态机决定"何时触发"，
17	 * 决策树在触发时提供特征证据（见 home.ux buildResultFor）。
18	 *
19	 * 可选 options：
20	 *   stillMs       跌倒确认所需静止时长（默认 8000，回放演示可调短）
21	 *   immobilityMs  异常静止所需低活动时长（默认 30000）
22	 *   onState       状态迁移回调 onState(type, detail)，用于可视化
23	 *                 type ∈ candidate | cancelled | fall | immobility
24	 */
25	
26	function magnitude(x, y, z) {
27	  return Math.sqrt(x * x + y * y + z * z)
28	}
29	
30	function variance(values) {
31	  if (!values.length) { return 0 }
32	  var avg = 0
33	  var i
34	  for (i = 0; i < values.length; i++) { avg += values[i] }
35	  avg = avg / values.length
36	  var total = 0
37	  for (i = 0; i < values.length; i++) {
38	    var d = values[i] - avg
39	    total += d * d
40	  }
41	  return total / values.length
42	}
43	
44	// 阈值（真机采样频率下的经验值）
45	var IMPACT_PEAK_G = 2.5      // 冲击峰值（g）
46	var MOVE_G = 1.6             // 候选期间超过此值视为恢复运动
47	var STILL_VAR = 0.05         // 冲击后静止方差阈值
48	var STILL_MS = 8000          // 跌倒确认需要的持续静止时长（默认）
49	var IMMOBILITY_VAR = 0.02    // 低活动方差阈值
50	var IMMOBILITY_MS = 30000    // 异常静止需要的持续低活动时长（默认）
51	var COOLDOWN_MS = 30000      // 两次事件之间的冷却
52	var ACTIVE_VAR = 0.05        // 判定"曾有过活动"的方差阈值
53	var ACTIVITY_WINDOW = 40     // 活动窗样本数
54	
55	export function createFallDetector(options) {
56	  options = options || {}
57	  var stillMs = options.stillMs || STILL_MS
58	  var immobilityMs = options.immobilityMs || IMMOBILITY_MS
59	  var onState = options.onState || function() {}
60	
61	  var state = "idle"         // idle | candidate
62	  var pre = []               // 冲击前短窗（g 值，找失重下限）
63	  var post = []              // 冲击后静止窗（g 值）
64	  var candidateAt = 0
65	  var candidatePeakG = 0
66	  var candidateMinG = 0
67	  var lastConfirmAt = 0
68	  var lastNow = 0
69	
70	  var stillSince = 0         // 持续低活动起始时间
71	  var hadActivity = false    // 是否曾出现过明显活动
72	  var activityWindow = []    // 短窗，用于当前低活动 & 曾否活动判定
73	
74	  function resetFall() {
75	    state = "idle"
76	    pre = []
77	    post = []
78	  }
79	
80	  function push(sample) {
81	    var g = magnitude(sample.x || 0, sample.y || 0, sample.z || 0)
82	    var now = sample.timestamp || Date.now()
83	    lastNow = now
84	    var cooldownOk = now - lastConfirmAt >= COOLDOWN_MS
85	
86	    // ── 活动窗维护（供异常静止使用）──
87	    activityWindow.push(g)
88	    if (activityWindow.length > ACTIVITY_WINDOW) { activityWindow.shift() }
89	    if (activityWindow.length >= 20) {
90	      if (variance(activityWindow) > ACTIVE_VAR) { hadActivity = true }
91	    }
92	
93	    // ── 跌倒：冲击候选 → 持续静止确认 ──
94	    if (state === "idle") {
95	      pre.push(g)
96	      if (pre.length > 20) { pre.shift() }
97	      if (g >= IMPACT_PEAK_G) {
98	        state = "candidate"
99	        candidateAt = now
100	        candidatePeakG = g
101	        candidateMinG = pre[0]
102	        for (var m = 1; m < pre.length; m++) {
103	          if (pre[m] < candidateMinG) { candidateMinG = pre[m] }
104	        }
105	        post = []
106	        onState("candidate", { peakG: candidatePeakG, minG: candidateMinG })
107	      }
108	    } else {
109	      // candidate
110	      if (g > MOVE_G) {
111	        var cancelledPeak = candidatePeakG
112	        resetFall()                       // 恢复运动 → 取消候选
113	        onState("cancelled", { peakG: cancelledPeak })
114	      } else {
115	        post.push(g)
116	        if (g > candidatePeakG) { candidatePeakG = g }
117	        var stillDur = now - candidateAt
118	        if (post.length >= 10 && variance(post.slice(-30)) <= STILL_VAR && stillDur >= stillMs) {
119	          resetFall()
120	          if (cooldownOk) {
121	            lastConfirmAt = now
122	            stillSince = 0
123	            var hit = {
124	              type: "fall",
125	              confidence: 0.9,
126	              at: now,
127	              stillMs: stillDur,
128	              peakG: candidatePeakG,
129	              minG: candidateMinG
130	            }
131	            onState("fall", hit)
132	            return hit
133	          }
134	        }
135	      }
136	    }
137	
138	    // ── 异常静止：曾活动 → 持续低活动 ──
139	    if (hadActivity && activityWindow.length >= 20 && variance(activityWindow) <= IMMOBILITY_VAR) {
140	      if (stillSince === 0) { stillSince = now }
141	      var immDur = now - stillSince
142	      if (immDur >= immobilityMs && cooldownOk) {
143	        lastConfirmAt = now
144	        stillSince = 0
145	        hadActivity = false
146	        var immHit = { type: "immobility", confidence: 0.9, at: now, stillMs: immDur }
147	        onState("immobility", immHit)
148	        return immHit
149	      }
150	    } else {
151	      stillSince = 0
152	    }
153	
154	    return null
155	  }
156	
157	  function getState() {
158	    return {
159	      state: state,
160	      stillMs: state === "candidate" ? (lastNow - candidateAt) : 0,
161	      peakG: candidatePeakG,
162	      hadActivity: hadActivity
163	    }
164	  }
165	
166	  return {
167	    push: push,
168	    reset: resetFall,
169	    getState: getState
170	  }
171	}
