1	/**
2	 * sensor-replay.js - 多传感器场景回放引擎
3	 *
4	 * 为加速度计、陀螺仪、心率、气压计提供同步的确定性 mock 数据。
5	 * 每种传感器的数据物理意义一致，便于端侧特征提取和决策树推理。
6	 */
7	
8	var SAMPLE_INTERVAL_MS = 80
9	
10	var SCENARIOS = [
11	  { id: "normal", title: "日常步行", subtitle: "低风险基线", samples: 40 },
12	  { id: "run", title: "正常跑步", subtitle: "验证不误报", samples: 44 },
13	  { id: "shake", title: "剧烈晃动", subtitle: "冲击但持续运动", samples: 44 },
14	  { id: "fall", title: "疑似跌倒", subtitle: "失重·冲击·静止", samples: 48 },
15	  { id: "immobility", title: "异常静止", subtitle: "长时间低活动", samples: 56 }
16	]
17	
18	// ─── 基础振荡函数 ──────────────────────────────────────
19	
20	function oscillation(index, speed) {
21	  return Math.sin(index * speed)
22	}
23	
24	// ─── 加速度计场景数据 ──────────────────────────────────
25	
26	function normalSample(index) {
27	  return {
28	    x: 0.08 * oscillation(index, 0.7),
29	    y: 0.06 * oscillation(index, 0.43),
30	    z: 1 + 0.08 * oscillation(index, 0.9)
31	  }
32	}
33	
34	function runSample(index) {
35	  return {
36	    x: 0.3 * oscillation(index, 1.1),
37	    y: 0.18 * oscillation(index, 0.73),
38	    z: 1.05 + 0.72 * oscillation(index, 1.45)
39	  }
40	}
41	
42	function shakeSample(index) {
43	  if (index === 12) {
44	    return { x: 2.6, y: 1.7, z: 1.4 }
45	  }
46	  return {
47	    x: 0.8 * oscillation(index, 1.9),
48	    y: 0.65 * oscillation(index, 1.2),
49	    z: 1 + 0.55 * oscillation(index, 1.55)
50	  }
51	}
52	
53	function fallSample(index) {
54	  if (index < 13) {
55	    return normalSample(index)
56	  }
57	  if (index === 13) {
58	    return { x: 0.08, y: 0.05, z: 0.18 }
59	  }
60	  if (index === 14) {
61	    return { x: 2.9, y: 1.7, z: 1.3 }
62	  }
63	  if (index < 21) {
64	    var decay = (21 - index) / 7
65	    return {
66	      x: 0.96 + 0.25 * decay * oscillation(index, 1.4),
67	      y: 0.08 * decay,
68	      z: 0.2 + 0.3 * decay
69	    }
70	  }
71	  return {
72	    x: 0.97 + 0.004 * oscillation(index, 0.5),
73	    y: 0.03,
74	    z: 0.18 + 0.004 * oscillation(index, 0.8)
75	  }
76	}
77	
78	function immobilitySample(index) {
79	  if (index < 6) {
80	    return { x: 0.03 + index * 0.002, y: 0.02, z: 0.99 }
81	  }
82	  return {
83	    x: 0.025 + 0.002 * oscillation(index, 0.31),
84	    y: 0.018 + 0.001 * oscillation(index, 0.47),
85	    z: 0.999 + 0.002 * oscillation(index, 0.27)
86	  }
87	}
88	
89	// ─── 陀螺仪场景数据 ──────────────────────────────────
90	
91	function gyroNormal(index) {
92	  return {
93	    x: 0.01 * oscillation(index, 0.6),
94	    y: 0.008 * oscillation(index, 0.45),
95	    z: 0.005 * oscillation(index, 0.3)
96	  }
97	}
98	
99	function gyroRun(index) {
100	  return {
101	    x: 0.25 * oscillation(index, 1.3),
102	    y: 0.15 * oscillation(index, 0.9),
103	    z: 0.08 * oscillation(index, 0.7)
104	  }
105	}
106	
107	function gyroShake(index) {
108	  if (index === 12) {
109	    return { x: 5.5, y: 3.2, z: 2.8 }
110	  }
111	  return {
112	    x: 0.7 * oscillation(index, 2.2),
113	    y: 0.5 * oscillation(index, 1.6),
114	    z: 0.35 * oscillation(index, 1.1)
115	  }
116	}
117	
118	function gyroFall(index) {
119	  if (index < 13) {
120	    return gyroNormal(index)
121	  }
122	  if (index === 13) {
123	    return { x: 6.2, y: 4.5, z: 3.8 }
124	  }
125	  if (index === 14) {
126	    return { x: 3.8, y: 2.2, z: 1.5 }
127	  }
128	  if (index < 21) {
129	    var decay = (21 - index) / 7
130	    return {
131	      x: 0.6 * decay * oscillation(index, 1.4),
132	      y: 0.4 * decay * oscillation(index, 1.1),
133	      z: 0.2 * decay * oscillation(index, 0.9)
134	    }
135	  }
136	  return { x: 0.005, y: 0.003, z: 0.002 }
137	}
138	
139	function gyroImmobility() {
140	  return { x: 0, y: 0, z: 0 }
141	}
142	
143	// ─── 心率场景数据 ──────────────────────────────────────
144	
145	function hrNormal(index) {
146	  return { heartRate: 72 + Math.round(2 * oscillation(index, 0.3)) }
147	}
148	
149	function hrRun(index) {
150	  return { heartRate: 88 + Math.round(index * 0.9 + 3 * oscillation(index, 0.5)) }
151	}
152	
153	function hrShake(index) {
154	  return { heartRate: 78 + Math.round(3 * oscillation(index, 0.4)) }
155	}
156	
157	function hrFall(index) {
158	  if (index < 13) {
159	    return { heartRate: 74 + Math.round(2 * oscillation(index, 0.3)) }
160	  }
161	  if (index < 20) {
162	    return { heartRate: 74 + Math.round((index - 13) * 4.5) }
163	  }
164	  return { heartRate: 103 + Math.round((index - 20) * 0.5 + 2 * oscillation(index, 0.2)) }
165	}
166	
167	function hrImmobility(index) {
168	  if (index < 20) {
169	    return { heartRate: 68 + Math.round(2 * oscillation(index, 0.25)) }
170	  }
171	  return { heartRate: 68 + Math.round((index - 20) * 0.85 + 2 * oscillation(index, 0.2)) }
172	}
173	
174	// ─── 气压计场景数据 ──────────────────────────────────
175	
176	function baroNormal(index) {
177	  return { pressure: 1013.25 + 0.1 * oscillation(index, 0.2) }
178	}
179	
180	function baroRun(index) {
181	  return { pressure: 1013.2 + 0.25 * oscillation(index, 0.6) }
182	}
183	
184	function baroShake(index) {
185	  return { pressure: 1013.25 + 0.15 * oscillation(index, 0.3) }
186	}
187	
188	function baroFall(index) {
189	  if (index < 14) {
190	    return { pressure: 1013.25 + 0.1 * oscillation(index, 0.2) }
191	  }
192	  var delta = -0.8 * Math.min((index - 14) / 6, 1)
193	  return { pressure: 1013.25 + delta + 0.05 * oscillation(index, 0.15) }
194	}
195	
196	function baroImmobility() {
197	  return { pressure: 1013.25 }
198	}
199	
200	// ─── 组装完整样本 ──────────────────────────────────────
201	
202	function makeSample(scenarioId, index) {
203	  var accel = normalSample(index)
204	  var gyro = gyroNormal(index)
205	  var hr = hrNormal(index)
206	  var baro = baroNormal(index)
207	
208	  if (scenarioId === "run") {
209	    accel = runSample(index); gyro = gyroRun(index); hr = hrRun(index); baro = baroRun(index)
210	  } else if (scenarioId === "shake") {
211	    accel = shakeSample(index); gyro = gyroShake(index); hr = hrShake(index); baro = baroShake(index)
212	  } else if (scenarioId === "fall") {
213	    accel = fallSample(index); gyro = gyroFall(index); hr = hrFall(index); baro = baroFall(index)
214	  } else if (scenarioId === "immobility") {
215	    accel = immobilitySample(index); gyro = gyroImmobility(index); hr = hrImmobility(index); baro = baroImmobility(index)
216	  }
217	
218	  return {
219	    // 加速度计（兼容原有格式）
220	    x: accel.x,
221	    y: accel.y,
222	    z: accel.z,
223	    timestamp: Date.now(),
224	    // 陀螺仪
225	    gyroX: gyro.x,
226	    gyroY: gyro.y,
227	    gyroZ: gyro.z,
228	    // 心率
229	    heartRate: hr.heartRate,
230	    // 气压计
231	    pressure: baro.pressure
232	  }
233	}
234	
235	// ─── 导出 ──────────────────────────────────────────────
236	
237	export function getScenarioCatalog() {
238	  return SCENARIOS
239	}
240	
241	export function createReplayEngine(callbacks) {
242	  var timer = null
243	
244	  function stop() {
245	    if (timer) {
246	      clearInterval(timer)
247	      timer = null
248	    }
249	  }
250	
251	  function start(scenarioId) {
252	    stop()
253	    var definition = SCENARIOS[0]
254	    for (var i = 0; i < SCENARIOS.length; i++) {
255	      if (SCENARIOS[i].id === scenarioId) {
256	        definition = SCENARIOS[i]
257	        break
258	      }
259	    }
260	
261	    var sampleIndex = 0
262	    if (callbacks.onStart) {
263	      callbacks.onStart(definition)
264	    }
265	
266	    timer = setInterval(function () {
267	      var sample = makeSample(definition.id, sampleIndex)
268	      if (callbacks.onSample) {
269	        callbacks.onSample(sample, sampleIndex + 1, definition.samples)
270	      }
271	      sampleIndex += 1
272	
273	      if (sampleIndex >= definition.samples) {
274	        stop()
275	        if (callbacks.onComplete) {
276	          callbacks.onComplete(definition)
277	        }
278	      }
279	    }, SAMPLE_INTERVAL_MS)
280	  }
281	
282	  return { start: start, stop: stop }
283	}
